const escapeHtml = (value) =>
  String(value ?? "").replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );

const formatDate = (iso) =>
  iso ? new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }) : "";

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  ul { list-style: none; padding: 0; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #777; }
  form.add { display: grid; gap: .5rem; margin-top: 1rem; }
  input, textarea, button { font: inherit; padding: .4rem; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 1rem; border-radius: 4px; }
  .error { color: #b00020; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const link = `<a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>`;
  const author = book.author ? ` <span class="muted">by ${escapeHtml(book.author)}</span>` : "";
  const action =
    book.status === "reading"
      ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button>Mark finished</button></form>`
      : `<span class="muted">${formatDate(book.finishedAt)}</span>`;
  return `<li><span>${link}${author}</span>${action}</li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="muted">${emptyText}</p>`;
  return `<ul>${books.map(bookItem).join("")}</ul>`;
}

export function homePage(books, { error, values = {} } = {}) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return layout(
    "My books",
    `<h2>Currently reading</h2>
${bookList(reading, "Nothing in progress.")}
<h2>Finished</h2>
${bookList(finished, "No finished books yet.")}
<h2>Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required value="${escapeHtml(values.title)}"></label>
  <label>Author <input name="author" value="${escapeHtml(values.author)}"></label>
  <label>Notes <textarea name="notes" rows="4">${escapeHtml(values.notes)}</textarea></label>
  <button>Add book</button>
</form>`,
  );
}

export function bookPage(book) {
  const status =
    book.status === "finished"
      ? `Finished ${formatDate(book.finishedAt)}`
      : `Reading since ${formatDate(book.addedAt)}`;
  const finishButton =
    book.status === "reading"
      ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button>Mark finished</button></form>`
      : "";
  return layout(
    book.title,
    `<h2>${escapeHtml(book.title)}</h2>
<p>${book.author ? `by ${escapeHtml(book.author)}` : `<span class="muted">Unknown author</span>`}</p>
<p class="muted">${status}</p>
<h3>Notes</h3>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
${finishButton}
<p><a href="/">&larr; All books</a></p>`,
  );
}

export function notFoundPage() {
  return layout("Not found", `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`);
}

