${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
${finishButton}
<p><a href="/">&larr; All books</a></p>`,
  );
}

export function notFoundPage() {
  return layout("Not found", `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`);
}

import { homePage, bookPage, notFoundPage } from "./views.js";

const MAX_BODY_BYTES = 64 * 1024;

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(Object.assign(new Error("Request too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(new URLSearchParams(Buffer.concat(chunks).toString("utf8"))));
    req.on("error", reject);
  });
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

// Returns a plain Node request handler: (req, res) => void.
export function createApp(store) {
  return async function handler(req, res) {
    try {
      const { pathname } = new URL(req.url, "http://localhost");
      const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
      const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);

      if (req.method === "GET" && pathname === "/") {
        return send(res, 200, homePage(store.all()));
      }

      if (req.method === "POST" && pathname === "/books") {
        const form = await readForm(req);
        const values = {
          title: (form.get("title") ?? "").trim(),
          author: (form.get("author") ?? "").trim(),
          notes: (form.get("notes") ?? "").trim(),
        };
        if (!values.title) {
          return send(res, 400, homePage(store.all(), { error: "A title is required.", values }));
        }
        await store.add(values);
        return redirect(res, "/");
      }

      if (req.method === "GET" && bookMatch) {
        const book = store.get(bookMatch[1]);
        return book ? send(res, 200, bookPage(book)) : send(res, 404, notFoundPage());
      }

      if (req.method === "POST" && finishMatch) {
        const book = await store.finish(finishMatch[1]);
        if (!book) return send(res, 404, notFoundPage());
        // Go back to wherever the button was clicked (home list or book page).
        const back = req.headers.referer ? new URL(req.headers.referer, "http://localhost").pathname : "/";
        return redirect(res, back === `/books/${book.id}` ? back : "/");
      }

      return send(res, 404, notFoundPage());
    } catch (err) {
      if (err.status === 413) return send(res, 413, "Request too large");
      console.error(err);
      if (!res.headersSent) send(res, 500, "Something went wrong");
    }
  };
}

import { createServer } from "node:http";
import { resolve } from "node:path";
import { openStore } from "./src/store.js";
import { createApp } from "./src/app.js";

const port = Number(process.env.PORT ?? 3000);
const dataFile = resolve(process.env.BOOKS_FILE ?? "data/books.json");

const store = await openStore(dataFile);
createServer(createApp(store)).listen(port, () => {
  console.log(`Reading list on http://localhost:${port} (saving to ${dataFile})`);
});

