import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { createServer } from "node:http";
import { mkdtemp, rm, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { openStore } from "../src/store.js";
import { createApp } from "../src/app.js";

let dir, file, server, base;

async function start() {
  const store = await openStore(file);
  server = createServer(createApp(store));
  await new Promise((r) => server.listen(0, r));
  base = `http://localhost:${server.address().port}`;
}
const stop = () => new Promise((r) => server.close(r));

const post = (path, fields = {}, headers = {}) =>
  fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(fields),
    headers,
    redirect: "manual",
  });

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("reading list", () => {
  it("shows empty sections on first open", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Nothing in progress.");
    expect(html).toContain("No finished books yet.");
  });

  it("adds a book, shows it as reading, and links to its page", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice!" });
    expect(res.status).toBe(303);
    expect(res.headers.get("location")).toBe("/");

    const [book] = JSON.parse(await readFile(file, "utf8"));
    expect(book).toMatchObject({ title: "Dune", author: "Frank Herbert", notes: "Spice!", status: "reading" });

    const home = await (await fetch(base + "/")).text();
    expect(home).toContain(`href="/books/${book.id}"`);
    expect(home).not.toContain("Nothing in progress.");

    const page = await fetch(`${base}/books/${book.id}`);
    expect(page.status).toBe(200);
    const html = await page.text();
    expect(html).toContain("Dune");
    expect(html).toContain("by Frank Herbert");
    expect(html).toContain("Spice!");
  });

  it("marks a book finished", async () => {
    await post("/books", { title: "Dune" });
    const [{ id }] = JSON.parse(await readFile(file, "utf8"));

    const res = await post(`/books/${id}/finish`);
    expect(res.status).toBe(303);

    const [book] = JSON.parse(await readFile(file, "utf8"));
    expect(book.status).toBe("finished");
    expect(book.finishedAt).toBeTruthy();

    const home = await (await fetch(base + "/")).text();
    expect(home).toContain("Nothing in progress.");
    expect(home).not.toContain("No finished books yet.");
  });

  it("returns to the book page when finishing from there", async () => {
    await post("/books", { title: "Dune" });
    const [{ id }] = JSON.parse(await readFile(file, "utf8"));
    const res = await post(`/books/${id}/finish`, {}, { Referer: `${base}/books/${id}` });
    expect(res.headers.get("location")).toBe(`/books/${id}`);
  });

  it("keeps books after a restart", async () => {
    await post("/books", { title: "Dune", notes: "Spice!" });
    await stop();
    await start();
    const home = await (await fetch(base + "/")).text();
    expect(home).toContain("Dune");
  });

  it("requires a title and keeps what was typed", async () => {
    const res = await post("/books", { title: "  ", author: "Someone" });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain("A title is required.");
    expect(html).toContain('value="Someone"');
  });

  it("escapes user input", async () => {
    await post("/books", { title: "<script>alert(1)</script>", notes: "<b>hi</b>" });
    const [{ id }] = JSON.parse(await readFile(file, "utf8"));
    const html = await (await fetch(`${base}/books/${id}`)).text();
    expect(html).not.toContain("<script>alert(1)</script>");
    expect(html).toContain("&lt;script&gt;");
  });

  it("404s for unknown books", async () => {
    expect((await fetch(base + "/books/nope")).status).toBe(404);
    expect((await post("/books/nope/finish")).status).toBe(404);
  });
});

